* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 32px 16px;

    font-family: Georgia, "Times New Roman", serif;
    background: #FAF3E0;
    display: flex;
    justify-content: center;
}

.bai-viet {
    width: min(800px, 100%);
}

.bai-viet h1 {
    margin: 0 0 22px;
    text-align: center;
    color: #E65100;
    font-size: 26px;
}

.bo-cuc {
    display: grid;
    grid-template-columns: 220px 1fr;
    gap: 24px;
    align-items: start;
}

.bo-cuc img {
    width: 100%;
    border-radius: 10px;
    display: block;
}

table {
    width: 100%;
    border-collapse: collapse;
    background: #ffffff;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
}

th, td {

     padding: 9px 12px;
     border-bottom: 1px solid #E0D6C2;
     text-align: left;
}

thead th {
     background: #E65100;
     color: #ffffff;
}

tbody tr:nth-child(even) {
     background: #FDF8EF;
}

th:first-child,
td:first-child {
     width: 60px;
     text-align: center;
}

@media (max-width: 600px) {
     .bo-cuc {
         grid-template-columns: 1fr;
     }
     .bo-cuc img {
         max-width: 200px;
         margin: 0 auto;
     }
}
